import { access, mkdir, writeFile, rm } from 'node:fs/promises';
import { join } from 'node:path';
let raw = '';
for await (const chunk of process.stdin) raw += chunk;
const request = JSON.parse(raw);
const marker = join(request.taskDir, 'prepared');
let result;
switch (request.operation) {
  case 'check': {
    const passed = await access(marker).then(() => true, () => false);
    result = { capabilities: { 'text.statistics': { status: passed ? 'ready' : 'not_ready', checks: [{ name: 'task_marker', passed }] } } };
    break;
  }
  case 'prepare':
    await mkdir(request.taskDir, { recursive: true }); await writeFile(marker, 'ready'); result = { prepared: true }; break;
  case 'invoke': {
    if (request.tool !== 'text_statistics' || !request.requested.includes('text.statistics')) throw new Error('Unknown tool');
    await access(marker);
    const text = request.args.text;
    if (typeof text !== 'string' || text.length > 65536) throw new Error('Invalid or oversized text');
    result = { codePoints: [...text].length, words: text.trim() ? text.trim().split(/\s+/u).length : 0 }; break;
  }
  case 'release': await rm(request.taskDir, { recursive: true, force: true }); result = { released: true }; break;
  default: throw new Error('Unknown operation');
}
process.stdout.write(JSON.stringify(result));
